+                    assertThat("all other shards should be started", shardMap.get("state"), equalTo("STARTED"));
+                    startedShards++;
+                }
+            }
+            assertThat(unassignedShards, equalTo(1));
+            assertThat(startedShards, equalTo(3));
+        });
